abstract class Shape { public abstract double Area(); }

sealed class Circle : Shape
{
    public double R;
    public override double Area() => Math.PI * R * R;
}

double One(Circle c) => c.Area(); // тип точно Circle: прямой вызов
double Any(Shape s) => s.Area();  // тип неизвестен: вызов через таблицу методов

